  function renderDeviceRecipeList(){const content=$('.content');if(!content)return;setCrumb('设备菜谱');pageState.selected.clear();content.innerHTML=`<div class="recipe-center-page" data-recipe-extension-page><div class="page-head"><div><button class="ghost recipe-back-button" id="backToDeviceHub">← 返回入口</button><h1>设备菜谱</h1><p>关联已发布且启用的标准菜谱，配置人工处理与设备加工流程。</p></div><button class="primary" id="createDeviceRecipeExtension">＋ 新建设备菜谱</button></div><div class="card device-list-card"><div class="filters device-basic-filters"><div class="search"><span>⌕</span><input id="deviceRecipeSearch" placeholder="搜索设备菜谱名称或编码"></div><select id="deviceRecipeStatus"><option value="">全部状态</option><option>开发中</option><option>已存档</option><option>已停用</option></select><button class="ghost" id="toggleAdvancedFilters">高级筛选</button><button class="ghost" id="resetDeviceRecipeFilter">重置</button><button class="secondary" id="batchRecipeTags" disabled>批量设置菜谱标签</button></div><div class="advanced-filters" id="advancedDeviceFilters" hidden><select id="filterRecipeCategory"><option value="">全部菜谱分类</option>${filterOptions('category')}</select><select id="filterRecipeProvince"><option value="">全部菜谱省份</option>${filterOptions('province')}</select><select id="filterRecipeTag"><option value="">全部菜谱标签</option>${tagFilterOptions()}</select><select id="filterRecipeCuisine"><option value="">全部菜系分类</option>${filterOptions('cuisine')}</select><input id="filterDeveloper" placeholder="研发人员"><label>创建时间<input id="filterCreatedStart" type="date"><input id="filterCreatedEnd" type="date"></label><label>更新时间<input id="filterUpdatedStart" type="date"><input id="filterUpdatedEnd" type="date"></label></div><div class="device-table-scroll"><table class="device-recipe-table"><thead><tr><th><input type="checkbox" id="checkAllDeviceRecipes"></th><th>菜谱信息</th><th>来源菜谱</th><th>基础分类</th><th>外语菜谱名</th><th>出餐成品系数</th><th>使用设备</th><th>设备加工步骤数</th><th>菜谱标签</th><th>状态</th><th>创建信息</th><th>更新信息</th><th>操作</th></tr></thead><tbody id="deviceRecipeExtensionBody">${deviceRows()}</tbody></table></div></div></div>`;$('#backToDeviceHub').onclick=renderDeviceHub;bindDevicePage()}
  function filterOptions(key){return (window.recipeDictionaryData?.[key]||[]).filter(x=>x.status==='启用').map(x=>`<option>${x.name}</option>`).join('')}
