  function deviceRows(){return pageState.records.map((r,i)=>`<tr data-keyword="${escapeHtml(r.name+' '+r.id+' '+r.source+' '+r.sourceCode)}" data-status="${r.status}" data-category="${escapeHtml(r.category||'')}" data-province="${escapeHtml(r.province||'')}" data-cuisine="${escapeHtml(r.cuisine||'')}" data-tags="${escapeHtml((r.tags||[]).join('|'))}" data-creator="${escapeHtml(r.creator||'')}" data-created="${escapeHtml(dateOnly(r.createdAt))}" data-updater="${escapeHtml(r.updater||'')}" data-updated="${escapeHtml(dateOnly(r.updatedAt||r.updated))}"><td><input type="checkbox" class="device-recipe-check" value="${i}"></td><td><div class="device-recipe-info"><div class="recipe-photo">菜</div><div><b>${escapeHtml(r.name)}</b><small>${r.id} · ${r.weight||'-'}克</small></div></div></td><td><div class="device-source-cell"><b>${escapeHtml(r.source)}</b><small>${r.sourceCode} · ${r.version}</small></div></td><td><div class="device-source-cell"><b>${escapeHtml(r.category||'-')}</b><small>${escapeHtml(r.cuisine||'-')}</small></div></td><td><b>${r.foreignCount||0}/10</b></td><td>${escapeHtml(r.yieldRate||'-')}</td><td><div class="device-tags device-maker-tags">${deviceLabels(r)}</div></td><td><div class="device-step-ratio"><b>${r.deviceSteps}/${r.totalSteps}</b><small>设备加工 / 全部步骤</small></div></td><td><span class="recipe-tag-count" data-tooltip="${escapeHtml(tagTooltip(r.tags))}">${(r.tags||[]).length}个标签</span></td><td><span class="recipe-status ${statusClass(r.status)}">${r.status}</span></td><td><div class="device-source-cell"><b>${escapeHtml(r.creator||'-')}</b><small>${escapeHtml(r.createdAt||'-')}</small></div></td><td><div class="device-source-cell"><b>${escapeHtml(r.updater||'-')}</b><small>${escapeHtml(r.updatedAt||r.updated||'-')}</small></div></td><td class="recipe-row-actions">${actionButtons(r,i)}</td></tr>`).join('')}
  function bindDevicePage(){const originalTagSelect=$('#filterRecipeTag'),tagGroups=(window.recipeDictionaryData?.tags||[]).filter(x=>x.status==='启用'),tagCascader=document.createElement('div');tagCascader.className='tag-cascader';tagCascader.innerHTML=`<button type="button" class="tag-cascader-trigger" id="filterRecipeTag"><span>全部菜谱标签</span><i>⌄</i></button><div class="tag-cascader-popup" id="tagCascaderPopup" hidden><div class="tag-cascader-parents" id="tagCascaderParents"><button type="button" data-tag-clear>全部标签</button>${tagGroups.map(x=>`<button type="button" data-tag-parent="${escapeHtml(x.name)}"><span>${escapeHtml(x.name)}</span><i>›</i></button>`).join('')}</div><div class="tag-cascader-children" id="tagCascaderChildren"><p>请选择一级标签</p></div></div>`;originalTagSelect.replaceWith(tagCascader);const tagTrigger=$('#filterRecipeTag'),tagPopup=$('#tagCascaderPopup'),tagChildren=$('#tagCascaderChildren');const refreshSelection=()=>{$('#batchRecipeTags').disabled=!pageState.selected.size;$('#checkAllDeviceRecipes').checked=pageState.selected.size===pageState.records.length};const inRange=(value,start,end)=>!value||((!start||value>=start)&&(!end||value<=end));const filter=()=>{const k=$('#deviceRecipeSearch').value.trim().toLowerCase(),s=$('#deviceRecipeStatus').value,cat=$('#filterRecipeCategory')?.value||'',province=$('#filterRecipeProvince')?.value||'',tag=tagTrigger.dataset.child||'',cuisine=$('#filterRecipeCuisine')?.value||'',dev=($('#filterDeveloper')?.value||'').trim().toLowerCase(),cs=$('#filterCreatedStart')?.value||'',ce=$('#filterCreatedEnd')?.value||'',us=$('#filterUpdatedStart')?.value||'',ue=$('#filterUpdatedEnd')?.value||'';$$('#deviceRecipeExtensionBody tr').forEach(row=>row.hidden=!!((k&&!row.dataset.keyword.toLowerCase().includes(k))||(s&&row.dataset.status!==s)||(cat&&row.dataset.category!==cat)||(province&&row.dataset.province!==province)||(tag&&!row.dataset.tags.split('|').includes(tag))||(cuisine&&row.dataset.cuisine!==cuisine)||(dev&&!`${row.dataset.creator} ${row.dataset.updater}`.toLowerCase().includes(dev))||!inRange(row.dataset.created,cs,ce)||!inRange(row.dataset.updated,us,ue)))};const clearTag=()=>{delete tagTrigger.dataset.group;delete tagTrigger.dataset.child;$('span',tagTrigger).textContent='全部菜谱标签';tagPopup.hidden=true;filter()};const showChildren=groupName=>{const group=tagGroups.find(x=>x.name===groupName);tagTrigger.dataset.group=groupName;$$('[data-tag-parent]').forEach(x=>x.classList.toggle('active',x.dataset.tagParent===groupName));tagChildren.innerHTML=(group?.children||[]).filter(x=>x.status==='启用').map(x=>`<button type="button" data-tag-child="${escapeHtml(x.name)}" class="${tagTrigger.dataset.child===x.name?'active':''}">${escapeHtml(x.name)}</button>`).join('');$$('[data-tag-child]',tagChildren).forEach(x=>x.onclick=()=>{tagTrigger.dataset.child=x.dataset.tagChild;$('span',tagTrigger).textContent=`${groupName} / ${x.dataset.tagChild}`;tagPopup.hidden=true;filter()})};tagTrigger.onclick=()=>{tagPopup.hidden=!tagPopup.hidden;if(!tagPopup.hidden&&!tagTrigger.dataset.group&&tagGroups[0])showChildren(tagGroups[0].name)};tagCascader.onclick=e=>e.stopPropagation();$$('[data-tag-parent]').forEach(x=>x.onclick=()=>showChildren(x.dataset.tagParent));$('[data-tag-clear]').onclick=clearTag;if(window.__closeDeviceTagCascader)document.removeEventListener('click',window.__closeDeviceTagCascader);window.__closeDeviceTagCascader=e=>{if(!tagCascader.contains(e.target))tagPopup.hidden=true};document.addEventListener('click',window.__closeDeviceTagCascader);$('#deviceRecipeSearch').oninput=filter;$('#deviceRecipeStatus').onchange=filter;$$('#advancedDeviceFilters select,#advancedDeviceFilters input').forEach(x=>x.oninput=filter);$('#toggleAdvancedFilters').onclick=e=>{const panel=$('#advancedDeviceFilters'),expanded=panel.hidden;panel.hidden=!expanded;if(!expanded)tagPopup.hidden=true;e.currentTarget.classList.toggle('active',expanded);e.currentTarget.setAttribute('aria-expanded',String(expanded));e.currentTarget.textContent=expanded?'收起筛选':'高级筛选'};$('#resetDeviceRecipeFilter').onclick=()=>{$('#deviceRecipeSearch').value='';$('#deviceRecipeStatus').value='';$$('#advancedDeviceFilters select,#advancedDeviceFilters input').forEach(x=>x.value='');clearTag();filter()};$('#createDeviceRecipeExtension').onclick=()=>openEditor();$('#checkAllDeviceRecipes').onchange=e=>{pageState.selected=new Set(e.target.checked?pageState.records.map((_,i)=>i):[]);$$('.device-recipe-check').forEach(x=>x.checked=e.target.checked);refreshSelection()};$$('.device-recipe-check').forEach(x=>x.onchange=()=>{x.checked?pageState.selected.add(+x.value):pageState.selected.delete(+x.value);refreshSelection()});$('#batchRecipeTags').onclick=()=>{const records=[...pageState.selected].map(i=>pageState.records[i]);window.openBatchRecipeTags(records,tags=>{records.forEach(r=>r.tags=[...new Set([...(r.tags||[]),...tags])]);renderDeviceRecipeList()})};$$('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action,+b.dataset.index))}
  function handleAction(action,index){const r=pageState.records[index];if(action==='view')return openDetail(r);if(action==='edit')return openEditor(r,index);if(action==='archive'){if(!confirm(`确认存档设备菜谱“${r.name}”吗？`))return;r.status='已存档';r.updated='刚刚';renderDeviceRecipeList();return toast('设备菜谱已存档')}if(action==='stop'){if(!confirm(`确认停用设备菜谱“${r.name}”吗？`))return;r.status='已停用';r.updated='刚刚';renderDeviceRecipeList();return toast('设备菜谱已停用')}if(action==='delete'){if(!confirm(`确认删除设备菜谱“${r.name}”吗？删除后不可恢复。`))return;pageState.records.splice(index,1);renderDeviceRecipeList();toast('设备菜谱已删除')}}
  function modal(title,desc,body){document.querySelector('#recipeExtensionModal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="recipe-modal-mask" id="recipeExtensionModal"><div class="recipe-modal"><div class="recipe-modal-head"><div><h2>${title}</h2><p>${desc}</p></div><button id="closeRecipeExtensionModal">×</button></div>${body}</div></div>`);$('#closeRecipeExtensionModal').onclick=closeModal}
