  function sourceIngredientDetails(source){const amountSets={DISH0018:['500','80','30','25'],DISH0061:['750','40','35','15'],DISH0042:['600','20','30','10'],DISH0035:['20','2','10','8']},amounts=amountSets[source.id]||[];return source.ingredients.map((name,i)=>({role:i===0?'主料':i===source.ingredients.length-1?'调味料':'辅料',food:name,amount:amounts[i]||'',unit:name==='鸡蛋'?'个':name.includes('调味')||name==='生抽'?'毫升':'克',state:'原料',cut:i===0?'切丁':'无需切配',spec:'',note:''}))}
  function defaultBaseInfo(source,existing=null){return {image:'',name:existing?.name||`${source.name}-设备方案`,alias:source.name,foreign:{},cooking:'炒',province:'全国',yieldRate:'100',intro:'',category:source.category.split(' / ')[0]||'大荤',cuisine:'川菜',tags:['动物性蛋白']}}
  function openEditor(existing=null,index=null){const existingDevice=deviceCatalog.flatMap(x=>x.models).find(x=>(existing?.devices||[]).includes(x.name))||null;pageState.draft={page:1,source:existing?sources.find(x=>x.name===existing.source)||null:null,name:existing?.name||'',activeStep:0,steps:[],ingredients:[],configTab:'basic',baseInfo:null,index,deviceBrand:existingDevice?.brand||'',deviceModel:existingDevice,deviceFlowEditing:false,deviceActionIndex:null};if(pageState.draft.source){pageState.draft.steps=sourceSteps(pageState.draft.source);pageState.draft.ingredients=sourceIngredientDetails(pageState.draft.source);pageState.draft.baseInfo=defaultBaseInfo(pageState.draft.source,existing)}modal(existing?'编辑设备菜谱':'新建设备菜谱','关联标准菜谱，选择设备型号后配置加工流程','<div class="recipe-wizard-steps" id="recipeWizardSteps"></div><div class="recipe-modal-body" id="recipeWizardBody"></div><div class="recipe-modal-foot"><button class="secondary" id="cancelRecipeWizard">取消</button><div class="spacer"></div><button class="secondary" id="prevRecipeWizard">上一步</button><button class="primary" id="nextRecipeWizard">下一步</button></div>');$('#cancelRecipeWizard').onclick=closeModal;$('#prevRecipeWizard').onclick=()=>{syncCurrentConfig();pageState.draft.deviceFlowEditing=false;pageState.draft.page--;drawWizard()};$('#nextRecipeWizard').onclick=nextWizard;drawWizard()}
  function drawSteps(){const labels=['选择来源与设备','配置菜谱','确认创建'];$('#recipeWizardSteps').innerHTML=labels.map((x,i)=>`<span class="${pageState.draft.page===i+1?'active':pageState.draft.page>i+1?'done':''}"><i>${pageState.draft.page>i+1?'✓':i+1}</i>${x}</span>`).join('')}
  function drawWizard(){drawSteps();$('#prevRecipeWizard').style.visibility=pageState.draft.page===1?'hidden':'visible';$('#nextRecipeWizard').textContent=pageState.draft.page===3?(pageState.draft.index===null?'创建设备菜谱':'保存修改'):'下一步';if(pageState.draft.page===1)drawSource();else if(pageState.draft.page===2)drawProcess();else drawConfirm()}
  function drawSource(){
    const d=pageState.draft,models=deviceCatalog.find(x=>x.brand===d.deviceBrand)?.models||[];
    $('#recipeWizardBody').innerHTML=`
      <section class="device-association-section">
        <div class="source-section-title"><div><h3>关联设备型号 <i>*</i></h3><p>一个设备菜谱必须关联一个设备型号。</p></div></div>
        <div class="device-cascade-select">
          <label>设备品牌<select id="deviceBrandSelect"><option value="">请选择设备品牌</option>${deviceCatalog.map(x=>`<option value="${x.brand}" ${x.brand===d.deviceBrand?'selected':''}>${x.brand}</option>`).join('')}</select></label>
          <span>›</span>
          <label>设备型号<select id="deviceModelSelect" ${d.deviceBrand?'':'disabled'}><option value="">请选择设备型号</option>${models.map(x=>`<option value="${x.id}" ${x.id===d.deviceModel?.id?'selected':''}>${x.name}</option>`).join('')}</select></label>
        </div>
      </section>
      <section class="source-select-section">
        <div class="source-section-title"><div><h3>关联标准菜谱 <i>*</i></h3><p>仅展示已发布且启用的标准菜谱</p></div><div class="standard-recipe-tools"><input id="standardSourceSearch" placeholder="搜索标准菜谱名称或编码"></div></div>
        <div class="standard-recipe-list">${sources.map(x=>`<label class="standard-recipe-choice ${d.source?.id===x.id?'active':''}" data-id="${x.id}" data-keyword="${x.name} ${x.id}"><input type="radio" name="standardRecipeSource" ${d.source?.id===x.id?'checked':''}><span><b>${x.name}</b><small>${x.id} · ${x.category}</small><small>${x.version} · 已发布 · 启用 · ${x.steps.length} 个步骤</small></span></label>`).join('')}</div>
      </section>`;
    $$('.standard-recipe-choice').forEach(c=>c.onclick=()=>{d.source=sources.find(x=>x.id===c.dataset.id);d.steps=sourceSteps(d.source);d.ingredients=sourceIngredientDetails(d.source);d.baseInfo=defaultBaseInfo(d.source);$$('.standard-recipe-choice').forEach(x=>x.classList.toggle('active',x===c))});
    $('#standardSourceSearch').oninput=e=>$$('.standard-recipe-choice').forEach(x=>x.hidden=!x.dataset.keyword.toLowerCase().includes(e.target.value.toLowerCase()));
    const changeDevice=(model,brand)=>{const configured=d.steps.some(x=>(x.deviceActions||[]).length);if(d.deviceModel?.id!==model?.id&&configured&&!confirm('更换或取消设备型号将清空所有设备加工配置，并将相关步骤切换为人工处理。是否继续？'))return false;if(d.deviceModel?.id!==model?.id){d.steps.forEach(x=>{x.deviceActions=[];x.mode='manual'})}d.deviceBrand=brand||model?.brand||'';d.deviceModel=model||null;return true};
    $('#deviceBrandSelect').onchange=e=>{const brand=e.target.value;if(!changeDevice(null,brand))return drawSource();drawSource()};
    $('#deviceModelSelect').onchange=e=>{const model=deviceCatalog.flatMap(x=>x.models).find(x=>x.id===e.target.value)||null;if(!changeDevice(model,d.deviceBrand))return drawSource();drawSource()};
  }
  function deviceContextBar(){const d=pageState.draft,m=d.deviceModel;return `<div class="device-context-bar ${m?'linked':'unlinked'}"><div class="device-context-icon">${m?'智谷':'—'}</div><div><b>${m?escapeHtml(m.name):'未关联设备型号'}</b><span>${m?`${m.brand} · ${m.boxes}个料盒 · 设备能力已加载`:'本菜谱仅支持人工处理，可返回第1步关联设备'}</span></div><button class="secondary" id="backToDeviceSelect">${m?'更换设备':'去关联设备'}</button></div>`}
  function drawProcess(){const d=pageState.draft;$('#recipeWizardBody').innerHTML=`<div class="device-config-tabs"><button class="${d.configTab==='basic'?'active':''}" data-config-tab="basic">1 基础信息</button><button class="${d.configTab==='ingredients'?'active':''}" data-config-tab="ingredients">2 用料明细</button><button class="${d.configTab==='process'?'active':''}" data-config-tab="process">3 加工步骤</button></div><div class="device-tab-content">${d.configTab==='basic'?basicInfoTab():d.configTab==='ingredients'?ingredientTab():processTab()}</div>`;$$('[data-config-tab]').forEach(b=>b.onclick=()=>{syncCurrentConfig();d.deviceFlowEditing=false;d.configTab=b.dataset.configTab;drawProcess()});if(d.configTab==='basic')bindBasicInfo();else if(d.configTab==='ingredients')bindIngredientTab();else bindProcessTab()}
  function dictionaryOptions(key,current){return (window.recipeDictionaryData?.[key]||[]).filter(x=>x.status==='启用').map(x=>`<option ${x.name===current?'selected':''}>${x.name}</option>`).join('')}
  function enabledTagOptions(selected){return (window.recipeDictionaryData?.tags||[]).filter(x=>x.status==='启用').map(p=>`<section><h4>${p.name}</h4><div>${p.children.filter(x=>x.status==='启用').map(x=>`<label><input type="checkbox" data-base-tag value="${x.name}" ${selected.includes(x.name)?'checked':''}> ${x.name}</label>`).join('')}</div></section>`).join('')}
  function basicInfoTab(){const b=pageState.draft.baseInfo,languageCount=Object.values(b.foreign).filter(Boolean).length;return `<section class="device-basic-section"><div class="device-basic-grid-v2"><div class="device-image-field"><span><i>*</i> 图片</span><label class="device-image-upload">${b.image?`<img src="${b.image}" alt="设备菜谱图片">`:'<b>＋</b><small>上传1张图片</small>'}<input id="deviceRecipeImage" type="file" accept="image/png,image/jpeg,image/webp"></label></div><div class="device-basic-fields"><label><i>*</i> 设备菜谱名称<input data-base-field="name" value="${escapeHtml(b.name)}"></label><label><i>*</i> 别名<input data-base-field="alias" value="${escapeHtml(b.alias)}"></label><label>外语菜谱名<button class="language-config-button" id="openLanguageConfig">已配语种 ${languageCount}/10 <em>设置 ›</em></button></label><label><i>*</i> 烹饪分类<select data-base-field="cooking">${dictionaryOptions('cooking',b.cooking)}</select></label><label><i>*</i> 菜谱省份<select data-base-field="province">${dictionaryOptions('province',b.province)}</select></label><label><i>*</i> 出餐成品系数<div class="percent-input"><input data-base-field="yieldRate" type="number" min="0.01" max="999.99" step="0.01" value="${b.yieldRate}"><span>%</span></div></label><label><i>*</i> 菜品分类<select data-base-field="category">${dictionaryOptions('category',b.category)}</select></label><label><i>*</i> 菜系分类<select data-base-field="cuisine">${dictionaryOptions('cuisine',b.cuisine)}</select></label><label class="full">菜品简介<textarea data-base-field="intro">${escapeHtml(b.intro)}</textarea></label></div></div><div class="base-tag-picker"><h3><i>*</i> 菜品标签 <small>可多选，只能选择二级标签</small></h3>${enabledTagOptions(b.tags)}</div></section>`}
  function bindBasicInfo(){const d=pageState.draft,b=d.baseInfo;$$('[data-base-field]').forEach(x=>x.oninput=()=>b[x.dataset.baseField]=x.value);$$('[data-base-tag]').forEach(x=>x.onchange=()=>b.tags=$$('[data-base-tag]:checked').map(x=>x.value));$('#openLanguageConfig').onclick=e=>{e.preventDefault();openLanguageConfig()};$('#deviceRecipeImage').onchange=e=>{const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{b.image=reader.result;drawProcess()};reader.readAsDataURL(file)}}
  function openLanguageConfig(){const b=pageState.draft.baseInfo,languages=['英文','法语','繁体中文','日语','韩语','越南语','西班牙语','德语','泰语','葡萄牙语'];document.body.insertAdjacentHTML('beforeend',`<div class="language-dialog-mask" id="languageDialog"><div class="language-dialog"><div class="language-dialog-head"><h3>配置外语菜谱名</h3><button id="closeLanguageDialog">×</button></div><div class="language-list">${languages.map(x=>`<label>${x}<input data-language="${x}" value="${escapeHtml(b.foreign[x]||'')}" placeholder="选填"></label>`).join('')}</div><div class="language-dialog-foot"><button class="secondary" id="cancelLanguageDialog">取消</button><button class="primary" id="saveLanguageDialog">保存</button></div></div></div>`);const close=()=>$('#languageDialog').remove();$('#closeLanguageDialog').onclick=close;$('#cancelLanguageDialog').onclick=close;$('#saveLanguageDialog').onclick=()=>{$$('[data-language]').forEach(x=>b.foreign[x.dataset.language]=x.value.trim());close();drawProcess()}}
  function ingredientCards(){const d=pageState.draft,options=(values,current)=>values.map(x=>`<option ${x===current?'selected':''}>${x}</option>`).join('');return d.ingredients.map((x,i)=>`<div class="device-ingredient-card" data-ingredient-row="${i}"><button class="ingredient-remove" data-remove-ingredient="${i}">删除</button><div class="device-ingredient-grid"><label>用料角色<select data-ingredient-field="role">${options(['主料','辅料','调味料'],x.role)}</select></label><label>标准食材<input data-ingredient-field="food" value="${escapeHtml(x.food)}"></label><label>投料量<input data-ingredient-field="amount" type="number" value="${x.amount}"></label><label>单位<select data-ingredient-field="unit">${options(['克','千克','毫升','升','个'],x.unit)}</select></label><label>投料状态<select data-ingredient-field="state">${options(['原料','净料','去皮后','泡发后','解冻后'],x.state)}</select></label><label>切配方式<select data-ingredient-field="cut">${options(['整只','切丝','切块','切片','切丁','无需切配'],x.cut)}</select></label><label>切配规格<input data-ingredient-field="spec" value="${escapeHtml(x.spec)}" placeholder="如约2cm见方"></label><label>说明<input data-ingredient-field="note" value="${escapeHtml(x.note)}"></label></div></div>`).join('')}
  function ingredientTab(){return `<section class="device-ingredient-section expanded"><div class="device-ingredient-head"><div><h3>用料明细 <span>${pageState.draft.ingredients.length}项</span></h3><p>已从标准菜谱复制为独立副本，修改不会影响来源菜谱。</p></div><button class="secondary" id="addDeviceIngredient">＋ 添加用料</button></div><div class="device-ingredient-list">${ingredientCards()}</div></section>`}
  function bindIngredientTab(){const d=pageState.draft;$('#addDeviceIngredient').onclick=()=>{syncIngredients();d.ingredients.push({role:'辅料',food:'',amount:'',unit:'克',state:'原料',cut:'无需切配',spec:'',note:''});drawProcess()};$$('[data-remove-ingredient]').forEach(b=>b.onclick=()=>{syncIngredients();d.ingredients.splice(+b.dataset.removeIngredient,1);drawProcess()})}
  function processTab(){const d=pageState.draft,s=d.steps[d.activeStep];return `<div class="process-layout"><aside class="process-nav"><h3>加工流程（${d.steps.length}步）</h3><div class="process-step-list">${d.steps.map((x,i)=>`<button class="${i===d.activeStep?'active':''}" data-step="${i}" data-process-card="${i}"><span class="process-drag-handle" draggable="true" data-process-drag="${i}" title="拖动调整顺序" aria-label="拖动第${i+1}步调整顺序">☷</span><i>${i+1}</i><b>${x.type}</b><span class="process-mode-tag ${x.mode==='device'?'device':'manual'}">${x.mode==='device'?'设备加工':'人工处理'}</span>${x.mode==='device'?`<em>${(x.deviceActions||[]).length}个设备操作步骤</em>`:''}<span class="process-delete-icon" role="button" tabindex="0" data-delete-step="${i}" title="删除流程" aria-label="删除第${i+1}步">×</span></button>`).join('')}</div><button class="process-add-step" id="addProcessStep">＋ 新增流程</button></aside><section class="process-editor"><div class="process-editor-head"><h3>步骤 ${d.activeStep+1} · ${s.type}</h3><div class="mode-switch"><button class="${s.mode==='manual'?'active':''}" data-mode="manual">人工处理</button><button class="${s.mode==='device'?'active':''}" data-mode="device" ${d.deviceModel?'':'disabled title="请先关联设备型号"'}>设备加工</button></div></div>${s.mode==='manual'?manualFields(s):deviceStepPanel(s)}</section></div>`}
  function processTypeOptions(current){const values=['预处理','腌制','焯水','炖制','炒制','蒸制','煮制','装盘'];if(current&&!values.includes(current))values.unshift(current);return values.map(x=>`<option ${x===current?'selected':''}>${x}</option>`).join('')}
  function processNamePicker(s){const items=(window.recipeDictionaryData?.process||[]).filter(x=>x.status==='启用'&&x.type===s.type),selected=items.find(x=>x.id===s.processId);return `<div class="process-name-picker" id="processNamePicker"><button type="button" class="process-name-trigger ${selected?'selected':''}" id="manualProcessName"><span>${selected?`${escapeHtml(selected.name)} <small>${escapeHtml(selected.id)}</small>`:'请选择工艺名称（选填）'}</span><i>⌄</i>${selected?`<em class="process-selected-preview"><b>${escapeHtml(selected.name)} · ${escapeHtml(selected.id)}</b><span>${escapeHtml(selected.steps)}</span></em>`:''}</button><div class="process-name-popup" id="processNamePopup" hidden><div class="process-name-search"><span>⌕</span><input id="processNameSearch" placeholder="搜索工艺名称或处理步骤"></div><div class="process-name-popup-body"><div class="process-name-results" id="processNameResults">${items.length?items.map(x=>`<button type="button" class="process-name-option ${x.id===s.processId?'active':''}" data-process-choice="${escapeHtml(x.id)}" data-keyword="${escapeHtml(`${x.name} ${x.steps}`.toLowerCase())}"><b>${escapeHtml(x.name)}<small>${escapeHtml(x.id)}</small></b><span>${escapeHtml(x.steps)}</span></button>`).join(''):'<p class="process-name-empty">该工艺类型暂无可用工艺名称</p>'}</div><aside class="process-name-preview" id="processNamePreview"><span>悬浮左侧工艺名称</span><p>可在这里查看完整处理步骤</p></aside></div></div></div>`}
  function deviceOperationCardDetails(x){const materials=x.materials||[],pot=[['火力',x.power],['搅拌方向',x.direction],['搅拌速度',x.speed],['锅口位置',x.position]];return `${materials.length?`<div class="device-operation-tag-row"><span>投料：</span><div>${materials.map(m=>`<i class="device-operation-tag material">${escapeHtml(m.food)}-${escapeHtml(m.amount||'')}${escapeHtml(m.unit||'')}</i>`).join('')}</div></div>`:''}<div class="device-operation-tag-row"><span>锅设置：</span><div>${pot.filter(x=>x[1]).map(x=>`<i class="device-operation-tag">${x[0]}：${escapeHtml(x[1])}</i>`).join('')}</div></div>${x.note?`<p class="device-operation-note"><b>备注：</b>${escapeHtml(x.note)}</p>`:''}`}
  function deviceStepPanel(s){const d=pageState.draft,actions=s.deviceActions||[],total=actions.reduce((n,x)=>n+(Number(x.duration)||0),0);let elapsed=0;return `<div class="device-step-panel"><div class="device-process-meta"><label>工艺类型<select data-field="type">${processTypeOptions(s.type)}</select></label><div><span>关联设备</span><b>${escapeHtml(d.deviceModel.brand)} · ${escapeHtml(d.deviceModel.name)}</b></div><div><span>设备操作步骤</span><b>${actions.length}步 · ${total}秒（${formatDeviceMinutes(total)}分钟）</b></div></div><div class="embedded-device-flow"><div class="embedded-device-flow-head"><div><h3>设备操作时间轴</h3><p>拖动步骤可调整执行顺序，起始时间将自动重新计算。</p></div><button class="primary" id="addDeviceOperation">＋ 添加设备操作步骤</button></div>${actions.length?`<section class="embedded-device-timeline">${actions.map((x,i)=>{const start=elapsed,hasMode=['solid','liquid','powder'].includes(x.type);elapsed+=Number(x.duration)||0;return `<article class="embedded-device-card ${i===d.deviceActionIndex?'active':''}" draggable="true" data-operation-card="${i}"><div class="embedded-device-marker"><i>${i+1}</i><span>☷ 拖动调整顺序　${formatDeviceTime(start)}</span></div><div class="embedded-device-card-body"><div class="embedded-device-card-title">${hasMode?`<b>投料模式：${actionModeLabel(x)}</b>`:'<b>操作设备</b>'}<strong>所需时间：${x.duration||0}S</strong></div>${deviceOperationCardDetails(x)}${i===d.deviceActionIndex?`<div class="embedded-device-card-actions"><button data-insert-operation="before" data-index="${i}">在此前添加</button><button data-edit-operation="${i}">编辑此步骤</button><button data-insert-operation="after" data-index="${i}">在此后添加</button><button class="danger" data-delete-operation="${i}">删除</button></div>`:''}</div></article>`}).join('')}</section>`:`<div class="device-flow-empty embedded-empty"><i>▦</i><b>暂无设备操作步骤</b><span>点击“添加设备操作步骤”配置第1步</span></div>`}</div></div>`}
  function bindProcessNamePicker(s){const picker=$('#processNamePicker'),trigger=$('#manualProcessName'),popup=$('#processNamePopup'),search=$('#processNameSearch'),preview=$('#processNamePreview');if(!picker||!trigger||!popup)return;picker.onclick=e=>e.stopPropagation();trigger.onclick=()=>{popup.hidden=!popup.hidden;if(!popup.hidden){search?.focus();const selected=$('[data-process-choice].active',popup);if(selected)selected.dispatchEvent(new Event('mouseenter'))}};if(search)search.oninput=()=>{const keyword=search.value.trim().toLowerCase();$$('[data-process-choice]',popup).forEach(x=>x.hidden=!x.dataset.keyword.includes(keyword))};$$('[data-process-choice]',popup).forEach(option=>{const item=(window.recipeDictionaryData?.process||[]).find(x=>x.id===option.dataset.processChoice);option.onmouseenter=()=>{if(preview&&item)preview.innerHTML=`<b>${escapeHtml(item.name)} <small>${escapeHtml(item.id)}</small></b><span>处理步骤</span><p>${escapeHtml(item.steps)}</p>`};option.onclick=()=>{syncStep();s.processId=item?.id||'';s.processName=item?.name||'';if(item)s.requirement=item.steps;drawProcess()}});if(window.__closeProcessNamePicker)document.removeEventListener('click',window.__closeProcessNamePicker);window.__closeProcessNamePicker=e=>{if(!picker.contains(e.target))popup.hidden=true};document.addEventListener('click',window.__closeProcessNamePicker)}
