  function closeDeviceOperationDrawer(){$('#deviceOperationDrawer')?.remove();if(pageState.draft)pageState.draft.operationDrawer=null}
  function operationDrawerTitle(kind,index,actions){if(kind==='edit')return `当前为第 ${index+1} 步`;if(kind==='before')return `在第 ${index+1} 步之前插入（新步骤将变为第 ${index+1} 步）`;if(kind==='after')return `在第 ${index+1} 步之后插入（新步骤将变为第 ${index+2} 步）`;return actions.length?`在第 ${actions.length} 步之后插入（新步骤将变为第 ${actions.length+1} 步）`:'当前为第 1 步'}
