  function renderDeviceOperationForm(){const host=$('.device-operation-drawer-content'),drawer=pageState.draft?.operationDrawer;if(!host||!drawer)return;host.innerHTML=deviceOperationForm(drawer.action);bindDeviceOperationForm()}
  function bindDeviceOperationForm(){const d=pageState.draft,a=d.operationDrawer.action;$$('[data-action-field]',$('#deviceOperationDrawer')).forEach(x=>x.oninput=()=>a[x.dataset.actionField]=x.value);$$('[data-action-type]',$('#deviceOperationDrawer')).forEach(x=>x.onclick=()=>{if(a.type!==x.dataset.actionType){a.type=x.dataset.actionType;a.materials=[];a.feedMethod='auto';a.box='1'}renderDeviceOperationForm()});$$('input[name="feedMethod"]',$('#deviceOperationDrawer')).forEach(x=>x.onchange=()=>{a.feedMethod=x.value;renderDeviceOperationForm()});$$('[data-action-material]',$('#deviceOperationDrawer')).forEach(x=>x.onchange=()=>{const food=x.dataset.actionMaterial,ingredient=d.ingredients.find(y=>y.food===food);if(x.checked&&!a.materials.some(y=>y.food===food))a.materials.push({food,amount:ingredient?.amount||'',unit:ingredient?.unit||''});if(!x.checked)a.materials=a.materials.filter(y=>y.food!==food);renderDeviceOperationForm()});$$('[data-material-amount]',$('#deviceOperationDrawer')).forEach(x=>x.oninput=()=>{const item=a.materials.find(y=>y.food===x.dataset.materialAmount);if(item)item.amount=x.value});const view=$('#viewDeviceBoxes'),popover=$('#deviceBoxPopover');if(view)view.onclick=()=>popover.hidden=!popover.hidden}
  function submitDeviceOperation(){const d=pageState.draft,drawer=d.operationDrawer,s=d.steps[d.activeStep],actions=s.deviceActions||[],a=drawer?.action,duration=Number(a?.duration);if(!a||!Number.isInteger(duration)||duration<=0)return toast('请输入所需时长（整数），不能为0');if(!a.power||!a.direction||!a.speed||!a.position)return toast('请完整选择锅设置');if(drawer.kind==='edit')actions[drawer.target]=a;else actions.splice(drawer.target,0,a);d.deviceActionIndex=drawer.target;closeDeviceOperationDrawer();drawProcess();toast(drawer.kind==='edit'?'设备操作步骤已修改':'设备操作步骤已添加')}
  function manualFields(s){const ingredients=pageState.draft.ingredients.map(x=>x.food).filter(Boolean);if(s.originalRequirement===undefined)s.originalRequirement=s.requirement;const changed=s.requirement!==s.originalRequirement;return `<div class="manual-step-grid"><label>工艺类型<select data-field="type">${processTypeOptions(s.type)}</select></label><label class="span2">工艺名称 <small>选填</small>${processNamePicker(s)}</label><label class="full">关联对象<div class="assoc-options">${['整道菜',...ingredients].map(x=>`<label><input type="checkbox" data-assoc="${x}" ${s.assoc.includes(x)?'checked':''}>${x}</label>`).join('')}</div></label><label class="full">操作要求<textarea data-field="requirement">${escapeHtml(s.requirement)}</textarea>${s.processId||changed?`<span class="process-reference-tip">${s.processId?`已引用工艺“${escapeHtml(s.processName)}（${escapeHtml(s.processId)}）”，内容可继续修改。`:'操作要求已修改。'}<button type="button" id="restoreOriginalRequirement">恢复原操作要求</button></span>`:''}</label><label class="span2">完成标准<input data-field="standard" value="${escapeHtml(s.standard)}"></label><label>注意事项<input data-field="attention" value="${escapeHtml(s.attention)}"></label></div>`}
